-- Conventions for every table:
--   id          UUID (v7, text) generated by the application; the primary key.
--   created_on  unix seconds, set on insert.
--   created_by  who created the row; NULL until accounts exist.
--   updated_on  unix seconds, NULL until the row is first updated, then set by a trigger.
--   updated_by  who last updated the row; NULL until accounts exist.
-- A NULL cost_usd means "not known yet / provider did not report".

CREATE TABLE sessions (
    id         TEXT PRIMARY KEY,
    kind       TEXT NOT NULL CHECK (kind IN ('blog', 'chat')),
    url        TEXT,
    created_on INTEGER NOT NULL DEFAULT (unixepoch()),
    created_by TEXT,
    updated_on INTEGER,
    updated_by TEXT
);
CREATE TRIGGER sessions_set_updated_on AFTER UPDATE ON sessions
FOR EACH ROW WHEN NEW.updated_on IS OLD.updated_on
BEGIN
    UPDATE sessions SET updated_on = unixepoch() WHERE id = NEW.id;
END;

CREATE TABLE messages (
    id         TEXT PRIMARY KEY,
    session_id TEXT NOT NULL REFERENCES sessions(id),
    role       TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
    text       TEXT,
    audio_key  TEXT,
    created_on INTEGER NOT NULL DEFAULT (unixepoch()),
    created_by TEXT,
    updated_on INTEGER,
    updated_by TEXT
);
CREATE INDEX messages_session ON messages(session_id);
CREATE TRIGGER messages_set_updated_on AFTER UPDATE ON messages
FOR EACH ROW WHEN NEW.updated_on IS OLD.updated_on
BEGIN
    UPDATE messages SET updated_on = unixepoch() WHERE id = NEW.id;
END;

-- Maps an adapter's own handle for a conversation (e.g. Telegram chat_id:message_id)
-- to a session, so threading works without Core knowing the platform.
CREATE TABLE thread_map (
    id         TEXT PRIMARY KEY,
    adapter    TEXT NOT NULL,
    thread_ref TEXT NOT NULL,
    session_id TEXT NOT NULL REFERENCES sessions(id),
    created_on INTEGER NOT NULL DEFAULT (unixepoch()),
    created_by TEXT,
    updated_on INTEGER,
    updated_by TEXT,
    UNIQUE (adapter, thread_ref)
);
CREATE TRIGGER thread_map_set_updated_on AFTER UPDATE ON thread_map
FOR EACH ROW WHEN NEW.updated_on IS OLD.updated_on
BEGIN
    UPDATE thread_map SET updated_on = unixepoch() WHERE id = NEW.id;
END;

-- One row per provider call. Inserted when the call succeeds; usage and cost
-- are filled in once the provider reports them (NULL until then).
CREATE TABLE ledger (
    id         TEXT PRIMARY KEY,
    session_id    TEXT NOT NULL REFERENCES sessions(id),
    role          TEXT NOT NULL CHECK (role IN ('llm', 'stt', 'tts')),
    provider      TEXT NOT NULL,
    model         TEXT NOT NULL,
    generation_id TEXT,
    chars         INTEGER NOT NULL DEFAULT 0,
    input_units   INTEGER,
    output_units  INTEGER,
    cost_usd      REAL,
    created_on INTEGER NOT NULL DEFAULT (unixepoch()),
    created_by TEXT,
    updated_on INTEGER,
    updated_by TEXT
);
CREATE INDEX ledger_session ON ledger(session_id);
CREATE TRIGGER ledger_set_updated_on AFTER UPDATE ON ledger
FOR EACH ROW WHEN NEW.updated_on IS OLD.updated_on
BEGIN
    UPDATE ledger SET updated_on = unixepoch() WHERE id = NEW.id;
END;

-- Cleaned article text, fetched once per URL.
CREATE TABLE page_cache (
    id         TEXT PRIMARY KEY,
    url_hash TEXT NOT NULL UNIQUE,
    url      TEXT NOT NULL,
    text     TEXT NOT NULL,
    created_on INTEGER NOT NULL DEFAULT (unixepoch()),
    created_by TEXT,
    updated_on INTEGER,
    updated_by TEXT
);
CREATE TRIGGER page_cache_set_updated_on AFTER UPDATE ON page_cache
FOR EACH ROW WHEN NEW.updated_on IS OLD.updated_on
BEGIN
    UPDATE page_cache SET updated_on = unixepoch() WHERE id = NEW.id;
END;

-- Finished audio per URL and voice settings, so re-sharing a link costs nothing.
CREATE TABLE audio_cache (
    id         TEXT PRIMARY KEY,
    url_hash  TEXT    NOT NULL,
    tts_model TEXT    NOT NULL,
    voice     TEXT    NOT NULL,
    audio_key TEXT    NOT NULL,
    seconds   INTEGER NOT NULL,
    created_on INTEGER NOT NULL DEFAULT (unixepoch()),
    created_by TEXT,
    updated_on INTEGER,
    updated_by TEXT,
    UNIQUE (url_hash, tts_model, voice)
);
CREATE TRIGGER audio_cache_set_updated_on AFTER UPDATE ON audio_cache
FOR EACH ROW WHEN NEW.updated_on IS OLD.updated_on
BEGIN
    UPDATE audio_cache SET updated_on = unixepoch() WHERE id = NEW.id;
END;
